using Npgsql;using AvenChart.Api.Models;namespace AvenChart.Api.Data;
public sealed class DocumentTemplateRepository(NpgsqlDataSource source){public async Task<IReadOnlyList<DocumentTemplateItem>> GetAsync(bool includeInactive,CancellationToken ct){await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText=$"select id,name,content,active,created_at,updated_at from document_templates {(includeInactive?"":"where active")} order by name;";var x=new List<DocumentTemplateItem>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(Read(r));return x;}public async Task<DocumentTemplateItem?> SaveAsync(Guid? id,DocumentTemplateRequest x,CancellationToken ct){if(string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.Content))throw new ArgumentException("Template name and text content are required.");await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();var key=id??Guid.NewGuid();q.CommandText=id is null?"insert into document_templates(id,name,content,active) values(@id,@name,@content,@active) returning id,name,content,active,created_at,updated_at;":"update document_templates set name=@name,content=@content,active=@active,updated_at=now() where id=@id returning id,name,content,active,created_at,updated_at;";q.Parameters.AddWithValue("id",key);q.Parameters.AddWithValue("name",x.Name.Trim());q.Parameters.AddWithValue("content",x.Content.Trim());q.Parameters.AddWithValue("active",x.Active);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?Read(r):null;}public async Task<DocumentTemplateRenderResult?> RenderAsync(Guid id,DocumentTemplateRenderRequest x,CancellationToken ct){await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="select t.id,t.name,t.content,t.active,t.created_at,t.updated_at,p.first_name,p.last_name,p.date_of_birth,p.pubpid from document_templates t join patients p on p.canonical_id=@patient where t.id=@id and t.active;";q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("patient",x.PatientId);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var t=Read(r);var content=t.Content.Replace("***NAME***",$"{r.GetString(6)} {r.GetString(7)}",StringComparison.Ordinal).Replace("***DOB***",r.GetFieldValue<DateOnly>(8).ToString("yyyy-MM-dd"),StringComparison.Ordinal).Replace("***PATIENT_ID***",r.GetString(9),StringComparison.Ordinal);return new(t,x.PatientId,content);}static DocumentTemplateItem Read(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetBoolean(3),r.GetFieldValue<DateTimeOffset>(4).ToString("O"),r.GetFieldValue<DateTimeOffset>(5).ToString("O"));}
